# Let's try reading the SQLite file directly with node's built-in fs
node -e "
const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
// Search for 'Daniel' in the raw bytes
const str = buf.toString('latin1');
const idx = str.indexOf('Daniel');
if (idx >= 0) {
  // Print surrounding context
  const start = Math.max(0, idx - 100);
  const end = Math.min(str.length, idx + 200);
  const snippet = buf.slice(start, end);
  console.log('Found Daniel at offset', idx);
  // Print printable chars
  let result = '';
  for (let i = 0; i < snippet.length; i++) {
    const c = snippet[i];
    if (c >= 32 && c < 127) result += String.fromCharCode(c);
    else result += ' | ';
  }
  console.log(result);
} else {
  console.log('Daniel not found in db');
}
"

